-- M32 exact source, grants, handoff evidence and predecessor compatibility.
DO $delivery_lineage_verify$
DECLARE item record;actual text;
BEGIN
 IF NOT EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=32) THEN RETURN;END IF;
 IF NOT EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=32 AND name='observer_retry_lineage') THEN RAISE EXCEPTION 'Delivery lineage migration identity drift';END IF;
 SELECT encode(sha256(convert_to(jsonb_build_object('table',jsonb_build_array(c.relkind,c.relpersistence,pg_get_userbyid(c.relowner),c.relrowsecurity,c.relforcerowsecurity,c.relreplident,c.reloptions),'acl',to_jsonb(c.relacl),'columns',(SELECT jsonb_agg(jsonb_build_array(a.attnum,a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attidentity,a.attgenerated,a.attcollation::regcollation::text,pg_get_expr(d.adbin,d.adrelid),a.attacl) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON(d.adrelid,d.adnum)=(a.attrelid,a.attnum) WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),'constraints',(SELECT jsonb_agg(jsonb_build_array(k.conname,k.contype,k.convalidated,k.condeferrable,k.condeferred,pg_get_constraintdef(k.oid,false)) ORDER BY k.conname) FROM pg_constraint k WHERE k.conrelid=c.oid),'indexes',(SELECT jsonb_agg(jsonb_build_array(ic.relname,i.indisvalid,i.indisready,pg_get_indexdef(i.indexrelid)) ORDER BY ic.relname) FROM pg_index i JOIN pg_class ic ON ic.oid=i.indexrelid WHERE i.indrelid=c.oid),'triggers',(SELECT jsonb_agg(jsonb_build_array(t.tgname,t.tgenabled,pg_get_triggerdef(t.oid,false)) ORDER BY t.tgname) FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal))::text,'UTF8')),'hex') INTO actual FROM pg_class c WHERE c.oid='forge_agent.delivery_lineage_handoffs'::regclass;
 IF actual IS DISTINCT FROM 'ffe68f29c3335c1a581f06770cee3802168361cbff292f2acfabddffba02b13b' THEN RAISE EXCEPTION 'Delivery lineage handoff table drift';END IF;
 FOR item IN SELECT * FROM(VALUES ('forge_agent._delivery_adopt_repair_lineage(uuid,uuid)','187a436f6a67405dccef00af80d49d4ff528387bad3f0bddce433d4e631c242e'),('forge_agent._delivery_lineage_blocked(text,text,uuid)','8eafd882b28ed40ce258f019ac7cc0f1eb2c6a39e62b80a6ef2201e5136ab572'),('forge_agent._delivery_lineage_legacy_source(oid,text)','3884015f87467b6991fe815fa5dbaa08c92f81ddd4248e85de93645378ba3def'),('forge_agent._delivery_lineage_patches()','57c7f9019fa99ca3d2a94f33a4a655f41088c3a84c70fd17f6aaede89f01c79a'),('forge_agent.delivery_lineage_handoff_immutable()','0f300e5130909ba9c445d6a2429c04c44b0bc68324e814df465101096ab2a2ab'),('forge_agent.delivery_register_post_merge(uuid)','932d48c0774d0988a989ebecade58bdff54cf69b1feb8ea7b388408639d0cdc7'),('forge_agent.delivery_repair_admit(uuid,integer,uuid,text)','656353567708bee305dca2dfcb07d1de93f1bd4a452cc41d14caf3138a8ef564'),('forge_agent.delivery_repair_checkpoint(uuid,integer,uuid,jsonb)','481a6212ea204b8c99a1b4ef0612f6594fe640c14d1cba57685a3e08e23c74a4'),('forge_agent.delivery_repair_claim(text)','d024937892f7a0e1109475b331fe2a2237e3aa086f30922c41ef345748297c98')) expected(signature,fingerprint) LOOP
 SELECT encode(sha256(convert_to(jsonb_build_array(pg_get_functiondef(p.oid),pg_get_userbyid(p.proowner),p.proacl)::text,'UTF8')),'hex') INTO actual FROM pg_proc p WHERE p.oid=to_regprocedure(item.signature);
 IF actual IS DISTINCT FROM item.fingerprint THEN RAISE EXCEPTION 'Delivery lineage authority drift: %',item.signature;END IF;
 END LOOP;
END;$delivery_lineage_verify$;
